import test from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import mockCmsData from '../src/data/mockCmsData.js';
import { createApp } from '../server/app.js';
import { createContentStore } from '../server/models/contentStore.js';

/** Gives each test isolated, disposable SQLite content instead of opening the live database. */
function testApp(t) {
  const contentStore = createContentStore({ databasePath: ':memory:', seed: mockCmsData });
  t.after(() => contentStore.close());
  return createApp({ contentStore });
}

test('GET content preserves the extracted CMS contract and sends security/cache headers', async t => {
  const response = await request(testApp(t)).get('/api/content').expect(200);
  assert.deepEqual(response.body, mockCmsData);
  assert.match(response.headers['cache-control'], /no-cache/);
  assert.equal(response.headers['x-content-type-options'], 'nosniff');
  assert.ok(response.headers['content-security-policy']);
  assert.ok(response.headers.etag);
  assert.equal(response.headers['x-powered-by'], undefined);
});
test('conditional content requests return 304', async t => {
  const app = testApp(t);
  const response = await request(app).get('/api/content');
  await request(app).get('/api/content').set('If-None-Match', response.headers.etag).expect(304);
});
test('CORS accepts configured origins and rejects unknown origins', async t => {
  const app = testApp(t);
  const response = await request(app).get('/api/content').set('Origin', 'http://127.0.0.1:5173').expect(200);
  assert.equal(response.headers['access-control-allow-origin'], 'http://127.0.0.1:5173');
  await request(app).get('/api/content').set('Origin', 'https://untrusted.example').expect(403);
  await request(app).options('/api/content').set('Origin', 'http://127.0.0.1:5173').set('Access-Control-Request-Method', 'GET').expect(204);
});
test('unknown routes and unsupported writes remain JSON 404s', async t => {
  const app = testApp(t);
  const response = await request(app).get('/api/missing').expect(404);
  assert.equal(response.body.error.code, 'NOT_FOUND');
  await request(app).post('/api/content').send({ site: 'overwrite' }).expect(404);
});
test('store errors are caught without leaking details', async () => {
  const app = createApp({
    contentStore: { read: async () => { throw new Error('private file path'); } },
    logger: { error() {} },
  });
  const response = await request(app).get('/api/content').expect(500);
  assert.equal(response.headers['cache-control'], 'no-store');
  assert.equal(response.body.error.message, 'Unable to complete this request.');
  assert.ok(!JSON.stringify(response.body).includes('private'));
});